        blocks_per_sm = 2048 // block_x
        needed = (n + block_x * 16 - 1) // (block_x * 16)
        grid_x = min(needed, sm_count * blocks_per_sm)

        _get_ptx_module().launch(
            "sigmoid_f32_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, y, u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

